SELECT mos.id, mos.code, mos.sc_id, mos.supplier_id, mos.material_user_id, mos.material_date, mos.material_order_id, mos.total_num, mos.total_amount, mos.description, mos.create_by, mos.create_by_id, mos.create_time, mos.update_by, mos.update_by_id, mos.update_time, mos.approve_by, mos.approve_time, mos.status, mos.refuse_reason, mos.tx_id FROM tbl_material_out_sheet mos LEFT JOIN shkb_material_order mo ON mos.material_order_id = mo.id
AND mos.code LIKE CONCAT('%', #{vo.code}, '%')
AND mos.sc_id = #{vo.scId}
AND mos.supplier_id = #{vo.supplierId}
AND mos.material_user_id = #{vo.materialUserId}
AND mos.material_order_id = #{vo.materialOrderId}
AND mos.status = #{vo.status}
AND mos.create_time >= #{vo.createTimeStart}
AND mos.create_time <= #{vo.createTimeEnd}
AND mos.create_by = #{vo.createBy}
AND mos.approve_by = #{vo.approveBy}
AND mos.approve_time >= #{vo.approveTimeStart}
AND mos.approve_time <= #{vo.approveTimeEnd}
AND mo.code LIKE CONCAT('%', #{vo.materialOrderCode}, '%')
ORDER BY mos.create_time DESC

SELECT mos.id AS id, mos.code AS code, mos.sc_id AS scId, sc.name AS scName, mos.supplier_id AS supplierId, s.name AS supplierName, mos.material_user_id AS materialUserId, u.name AS materialUserName, mos.material_order_id AS materialOrderId, mo.code AS materialOrderCode, mos.total_num AS totalNum, mos.total_amount AS totalAmount, mos.status AS status, mos.description AS description, mos.create_by AS createBy, mos.create_time AS createTime, au.name AS approveBy, mos.approve_time AS approveTime FROM tbl_material_out_sheet mos LEFT JOIN base_data_store_center sc ON mos.sc_id = sc.id LEFT JOIN base_data_supplier s ON mos.supplier_id = s.id LEFT JOIN sys_user u ON mos.material_user_id = u.id LEFT JOIN sys_user au ON mos.approve_by = au.id LEFT JOIN shkb_material_order mo ON mos.material_order_id = mo.id
AND mos.code LIKE CONCAT('%', #{vo.code}, '%')
AND mos.sc_id = #{vo.scId}
AND mos.supplier_id = #{vo.supplierId}
AND mos.material_user_id = #{vo.materialUserId}
AND mos.material_order_id = #{vo.materialOrderId}
AND mos.status = #{vo.status}
AND mos.create_time >= #{vo.createTimeStart}
AND mos.create_time <= #{vo.createTimeEnd}
AND mos.create_by = #{vo.createBy}
AND mos.approve_by = #{vo.approveBy}
AND mos.approve_time >= #{vo.approveTimeStart}
AND mos.approve_time <= #{vo.approveTimeEnd}
AND mo.code LIKE CONCAT('%', #{vo.materialOrderCode}, '%')
ORDER BY mos.create_time DESC

